linkedList:
```cpp
template <typename N>
template <typename Ring>
typename Earcut<N>::Node*
Earcut<N>::linkedList(const Ring& points, const bool clockwise) {
    using Point = typename Ring::value_type;
    double sum = 0;
    const std::size_t len = points.size();
    std::size_t i = 0;
    std::size_t j = len > 0 ? len - 1 : 0;
    while (i < len) {
        const auto& p1 = points[i];
        const auto& p2 = points[j];
        const double p20 = util::get<0>(p2);
        const double p00 = util::get<0>(p1);
        const double p11 = util::get<1>(p1);
        const double p01 = util::get<1>(p2);
        sum += (p20 - p00) * (p11 + p01);
        j = i;
        i++;
    }

    //link points into circular doubly-linked list in the specified winding order
    Node* last = nullptr;
    if (clockwise == (sum > 0)) {
        for (i = 0; i < len; i++) last = insertNode(vertices + i, util::get<0>(points[i]), util::get<1>(points[i]), last);
    } else {
        for (i = len; i-- > 0;) last = insertNode(vertices + i, util::get<0>(points[i]), util::get<1>(points[i]), last);
    }

    if (last && equals(last, last->next)) {
        removeNode(last);
        last = last->next;
    }

    vertices += len;

    return last;
}
```

